const serviceFaqs: Record<string,{q:string;a:string}[]> = {
  "custom-software-development":[{q:"When does custom software make sense instead of another SaaS tool?",a:"Custom software is useful when the workflow, data, permissions, or integrations create a meaningful advantage that standard tools cannot support without heavy workarounds."},{q:"Can you work with an existing codebase?",a:"Yes. A defined feature, repair, or workflow can be delivered inside an existing codebase after its architecture, access, and acceptance conditions are understood."},{q:"Can you handle product design and backend together?",a:"Yes. The engagement can connect user flow, interface, application logic, data, integrations, testing, and deployment as one delivery path."},{q:"What should I prepare before we start?",a:"Share the user, current workflow, desired result, constraints, useful links, and any systems the product must connect to. An early brief is enough to begin scoping."}],
  "saas-development":[{q:"Can you build a SaaS product from an early idea?",a:"Yes. The first step is to define the customer job, smallest complete workflow, account model, operational needs, and assumptions the first release must test."},{q:"Can billing, roles, and admin workflows be included?",a:"Yes, when they are needed for the first useful release. They are scoped around real account, permission, support, and product requirements."},{q:"Can you improve an existing SaaS product?",a:"Yes. A project can focus on activation, a difficult feature, data architecture, integrations, performance, or a clearer operational workflow."},{q:"What does the client own?",a:"The client should control the repository, deployment, data services, and essential third-party accounts, with documentation for release and handoff."}],
  "web-application-development":[{q:"What is included beyond the frontend?",a:"A web application engagement can include data models, authorization, APIs, integrations, validation, testing, deployment, and the loading and failure states users encounter."},{q:"Can you build dashboards and internal portals?",a:"Yes. Dashboards, operational consoles, customer portals, and multi-step workflows are a strong fit when the important decisions and actions are clearly defined."},{q:"Will the application work on mobile?",a:"Responsive behavior is planned around the workflow and verified across practical mobile, tablet, and desktop sizes."},{q:"Can you integrate an existing backend?",a:"Yes. Existing APIs and services can be used after their contracts, authentication, error behavior, and ownership boundaries are reviewed."}],
  "api-integration-development":[{q:"What types of APIs can you integrate?",a:"REST APIs, webhooks, payments, identity, GitHub, market-data, blockchain, and other documented services can be connected when access and contracts are available."},{q:"How are failed webhooks or API calls handled?",a:"The design can include validation, idempotency, retries, logging, recoverable states, and visible records so failures do not disappear silently."},{q:"Can you repair an unreliable integration?",a:"Yes. The first step is to reproduce the failure, map the contract and limits, and identify whether the issue is authentication, data shape, timing, retries, or product state."},{q:"Can several systems be synchronized?",a:"Yes, with one explicit source of truth, mapped ownership, and clear conflict and recovery rules."}],
  "business-automation":[{q:"What should be automated first?",a:"Start with a repeatable workflow that has clear inputs, decisions, exceptions, and an observable result. Preserve human judgment where the decision is high risk or ambiguous."},{q:"Can you replace a spreadsheet workflow?",a:"Yes, when the spreadsheet is carrying shared state, approvals, reminders, or reporting that would benefit from roles, validation, and a clearer audit trail."},{q:"Will people still be able to review decisions?",a:"Yes. Approval points, evidence, overrides, and activity records can remain visible instead of hiding the process behind a black box."},{q:"Can the tool connect to our current software?",a:"Usually, if the existing tools expose appropriate APIs, webhooks, exports, or other supported interfaces."}],
  "mvp-product-development":[{q:"How small should an MVP be?",a:"It should be the smallest release that lets the intended user complete one meaningful workflow with enough real data and operational behavior to generate useful evidence."},{q:"Is a prototype the same as an MVP?",a:"No. A prototype can demonstrate an idea; an MVP must support a real user task, data boundary, release, and feedback loop."},{q:"Can you help decide the first-release scope?",a:"Yes. Scope is shaped around the riskiest product assumption, critical path, required integrations, acceptance conditions, and what can safely wait."},{q:"What happens after launch?",a:"Observed friction and user behavior should determine the next scope. The handoff can include the repository, deployment, documentation, and a prioritized next-step brief."}],
  "ai-application-development":[{q:"When should a workflow use an AI agent?",a:"Use an agent when the task benefits from model reasoning and controlled tool use. Deterministic rules are usually better for fixed calculations, permissions, and irreversible actions."},{q:"Can AI connect to our existing data and tools?",a:"Yes, through scoped retrieval, APIs, and explicit tool contracts, with permissions and sensitive-data boundaries designed before release."},{q:"How do you reduce incorrect AI output?",a:"Use structured inputs and outputs, retrieval where appropriate, validation, constrained tools, test sets, human review, and fallbacks rather than relying on one prompt."},{q:"Can an AI feature be added to an existing product?",a:"Yes. It can be introduced as a defined workflow with observable behavior, cost controls, and a non-AI fallback where the product requires one."}],
  "product-rescue":[{q:"Do you recommend a rewrite?",a:"Only when evidence shows the current system cannot support the required workflow safely or economically. Most rescue work should first isolate the critical path, reproduce failures, and compare focused repair with replacement."},{q:"Can you work on an AI-generated codebase?",a:"Yes. The code is treated as untrusted until contracts, tests, security boundaries, data behavior, and release steps are verified against the product workflow."},{q:"What happens during the first assessment?",a:"The assessment maps the release path, reproduces high-impact failures, reviews ownership and deployment, and produces a ranked plan with explicit assumptions and stop conditions."},{q:"Can rescue work be delivered in phases?",a:"Yes. A common sequence is assessment, critical-path stabilization, integration and data repair, release verification, then maintainability improvements that are justified by observed risk."}],
};

const guides: Guide[] = [
  { slug:"hire-saas-developer", category:"Hiring", service:"saas-development", proof:["meridian","resolve"], title:"How to hire a SaaS developer for a product people can use", description:"A practical guide to evaluating SaaS product scope, architecture, integrations, delivery, ownership, and handoff.", intro:"Hire around a customer workflow, not a list of framework names. A strong SaaS developer should connect the account, data, interface, permissions, integrations, and deployment into one maintainable product.", sections:[
    ["Start with the customer job","Define who the first user is, what they need to accomplish, what information they need, and what changes after success. Ask the developer to identify the smallest complete path and the assumptions that still need validation."],
    ["Review the whole product boundary","Inspect more than the interface. Discuss account creation, roles, records, authorization, integrations, billing-adjacent states, operational access, and how failures will appear to a user or administrator."],
    ["Ask for evidence, not confidence","Use live projects, source code, technical decisions, and a walkthrough of a difficult state as evidence. Agree on repository ownership, environments, acceptance conditions, deployment, and handoff before the build expands."],
    ["Plan the first release","A useful first release should complete one important job with real data and meaningful feedback. Leave broad settings, secondary roles, and speculative dashboards until actual use shows they are needed."]
  ]},
  { slug:"hire-web-app-developer", category:"Hiring", service:"web-application-development", proof:["meridian","agora-forge"], title:"How to hire a web app developer without buying a collection of screens", description:"A practical guide to reviewing frontend, backend, data, integrations, testing, ownership, and deployment.", intro:"Hire a web app developer around a workflow, not a page count. The right person connects the interface a user sees with the data, rules, integrations, and deployment behind it.", sections:[
    ["Begin with the user flow","Describe who arrives, what information they need, what action they take, and what changes after success. Include loading, empty, permission, validation, and error states."],
    ["Review frontend, backend, and data together","Ask how the interface clarifies the main state and next action, how records are validated, and how authorization is enforced beyond hiding a button."],
    ["Test integration thinking","For every API or webhook, agree on inputs, expected output, failure behavior, retries, and account ownership. A happy-path demo is not a complete integration."],
    ["Make handoff part of delivery","The client should control the repository, hosting, data service, and key integrations. Document environment variables, release steps, and the acceptance conditions for the working flow."]
  ]},
  { slug:"startup-mvp-development", category:"Planning", service:"mvp-product-development", proof:["meridian","agora-forge"], title:"Startup MVP development: build a complete learning loop, not a demo", description:"A practical scope guide for defining a smallest complete workflow, choosing data and integrations, launching, and learning.", intro:"A useful MVP proves one meaningful workflow with real users. It does not need every future feature, but it needs enough interface, data, and operational reality for someone to finish the task.", sections:[
    ["Start with a testable hypothesis","Name the specific person, recurring problem, valuable outcome, and observable behavior that would change your next decision. Keep the first audience narrow."],
    ["Define the smallest complete workflow","Give the release an entry point, required information, an action, a visible result, and recovery when something goes wrong. Use real data boundaries where placeholders would hide risk."],
    ["Choose data, roles, and integrations carefully","Store only what the first workflow requires. Limit roles and connect external services only when the result would otherwise be misleading."],
    ["Avoid the demo-only MVP","Include access, incomplete input, empty data, failure states, repository ownership, and deployment. Choose the next scope from observed user friction rather than a speculative backlog."]
  ]},
  { slug:"custom-software-vs-saas", category:"Build or buy", service:"custom-software-development", proof:["resolve","repodiet"], title:"Custom software vs SaaS: a practical build-or-buy decision", description:"Use workflow fit, differentiation, ownership, integration, risk, and lifetime cost to decide whether to buy software, extend it, or build a custom system.", intro:"Buy when a mature tool supports the workflow without distorting it. Build when the workflow is strategically important, unusually specific, or depends on data and integrations that packaged software cannot support cleanly. The right answer may also be a hybrid: buy the commodity layer and build the differentiating workflow around it.", sections:[
    ["Start with workflow fit","List the user, decisions, records, exceptions, and systems involved. A SaaS tool is a strong choice when it supports those needs with modest configuration. Custom software becomes more defensible when workarounds create repeated manual handoffs, poor visibility, or compromised decisions."],
    ["Compare lifetime ownership, not only build cost","Include subscriptions, implementation, migration, integration, customization, internal administration, vendor limits, maintenance, security, support, and future change. A lower first-year price can still create a higher long-term operating burden."],
    ["Separate commodity from differentiation","Authentication, email, payments, storage, and observability are often better purchased or integrated. The workflow, data model, and decision surface that make the business distinct may be worth owning."],
    ["Choose a reversible first step","Test the decision with a narrow integration, internal tool, or critical-path release. Define what evidence would justify expanding the custom system and what conditions would send the team back to an off-the-shelf option."]
  ]},
  { slug:"saas-mvp-development-cost", category:"Cost & scope", service:"mvp-product-development", proof:["meridian","resolve"], title:"SaaS MVP development cost: what actually changes the scope", description:"A scope-first guide to the product, data, integrations, operations, and release decisions that determine the real cost of a SaaS MVP.", intro:"A responsible SaaS MVP estimate cannot come from a page count. Cost changes with the customer workflow, account and permission model, data complexity, integrations, operational tools, quality bar, and how much uncertainty must be resolved before release. Define those boundaries before discussing a number.", sections:[
    ["The customer workflow is the main cost driver","A narrow workflow with one user type and one core outcome is different from a platform with several roles, approvals, billing states, and administrative operations. Write the smallest complete journey first."],
    ["Account, data, and permissions add hidden scope","Authentication alone is not the full account system. Teams must decide invitations, organizations, roles, authorization, deletion, exports, support access, and how records are owned."],
    ["Integrations need failure handling","Payments, email, AI models, market data, and other APIs add contracts, limits, webhooks, retries, monitoring, and account ownership. Estimate the failure paths, not just the successful demo."],
    ["Estimate with acceptance conditions","Break the release into observable outcomes and include design decisions, implementation, testing, deployment, documentation, and handoff. Keep speculative secondary features outside the first estimate."]
  ]},
  { slug:"api-integration-planning", category:"Architecture", service:"api-integration-development", proof:["resolve","agora-forge"], title:"API integration planning: contracts, failures, ownership, and launch", description:"Plan an API integration around authentication, data contracts, limits, retries, webhooks, observability, testing, and operational ownership.", intro:"A dependable API integration is a product workflow with external dependencies, not a single request. Before implementation, define the contract, source of truth, authentication, limits, success state, failure behavior, and who can resolve a problem after launch.", sections:[
    ["Map the contract and source of truth","Document required inputs, returned fields, identifiers, versioning, and which system owns each record. Define how duplicates, missing data, and conflicting updates are resolved."],
    ["Design authentication and permissions","Clarify OAuth or key ownership, scopes, token storage, rotation, test environments, and whether individual users or one service account authorize the connection."],
    ["Make failures recoverable","Plan timeouts, rate limits, validation errors, retries, idempotency, webhook ordering, dead-letter handling, and a visible state that explains what needs attention."],
    ["Test operations, not only requests","Verify sandbox and production differences, logging, alerting, replay, reconciliation, privacy, and the manual process for incidents. Assign ownership for credentials and provider changes after handoff."]
  ]},
  { slug:"rescue-ai-built-web-app", category:"Product rescue", service:"product-rescue", proof:["repodiet","meridian"], published:"2026-09-27", title:"How to rescue an AI-built web app without starting over", description:"A practical method for assessing, stabilizing, testing, and releasing an AI-built or inherited web application.", intro:"Do not begin with a rewrite. First identify the product's critical workflow, reproduce its failures, establish who owns the data and deployment, and create a narrow release boundary that can be verified. Replace code only where the existing path cannot be made dependable at a reasonable cost.", sections:[
    ["Freeze the critical path","Name the first user, the one result that must work, and the states required to reach it. Pause speculative features until that path is reproducible in a controlled environment."],
    ["Turn symptoms into evidence","Record exact inputs, environment, logs, data state, expected behavior, and actual behavior for each failure. Separate product gaps from code defects, configuration problems, integration failures, and missing operational ownership."],
    ["Repair boundaries before polish","Prioritize authentication, authorization, data integrity, API contracts, error recovery, deployment, and monitoring. Visual cleanup cannot compensate for an unreliable state transition or an unknown source of truth."],
    ["Release with explicit proof","Define acceptance checks for the critical path, run them against the release build, document known limitations, and keep a rollback path. The next scope should come from observed failure and user friction, not code aesthetics."]
  ]},
  { slug:"ai-feature-vs-automation", category:"AI product", service:"ai-application-development", proof:["repodiet","resolve"], published:"2026-09-27", title:"AI feature vs automation: choose the right product architecture", description:"Decide when a workflow needs model reasoning, deterministic automation, human review, or a controlled combination of all three.", intro:"Use deterministic automation when inputs and rules are known. Use an AI feature when interpretation or generation adds real value and the result can be evaluated. Use an agent only when controlled tool use is necessary. High-impact decisions still need permissions, validation, and a human or deterministic guardrail.", sections:[
    ["Classify the decision","Write the input, allowed actions, output, cost of error, and how correctness will be judged. If the same input should always produce the same action, begin with deterministic logic."],
    ["Give models a bounded role","Use the model for classification, extraction, synthesis, or generation where ambiguity is real. Keep identity, authorization, money movement, deletion, and irreversible state changes behind explicit product rules."],
    ["Design evaluation before launch","Create representative success, edge, and failure cases. Track usefulness, incorrect output, refusal, latency, and cost. A demo prompt is not an evaluation plan."],
    ["Keep recovery visible","Show users when AI is involved, preserve source context where appropriate, provide review or correction, and define what happens when the model or an external tool is unavailable."]
  ]},
  { slug:"reliable-webhook-integration", category:"Architecture", service:"api-integration-development", proof:["resolve","agora-forge"], published:"2026-09-27", title:"Reliable webhook integration: retries, idempotency, and recovery", description:"A practical checklist for building webhook workflows that survive duplicates, delays, reordering, and provider failures.", intro:"Treat every webhook as an untrusted, repeatable event. Verify authenticity, acknowledge quickly, make processing idempotent, store enough context to retry safely, and expose failures to an operator. Delivery order and one-time execution should never be assumed unless the provider explicitly guarantees them.", sections:[
    ["Verify and acknowledge","Validate the provider signature against the raw request body, reject stale or invalid requests, and return the required success response quickly. Move slow work out of the request path when the platform supports it."],
    ["Make processing idempotent","Use the provider event ID or a stable business key to prevent duplicate effects. Store processing state and design database writes so a retry cannot charge, notify, or mutate the same record twice."],
    ["Expect delay and reordering","Fetch current provider state when an event alone is insufficient. Model transitions explicitly and avoid assuming that creation, update, and completion events arrive once or in sequence."],
    ["Build an operator recovery path","Record sanitized payload metadata, attempt count, error, and next action. Use bounded retries, a dead-letter state, alerting, replay controls, and reconciliation for events that cannot be processed automatically."]
  ]},
];

