const routeList = ["services","work","guides","about","contact", ...services.map(s=>`services/${s.slug}`), ...projects.map(p=>`work/${p.slug}`), ...guides.map(g=>`guides/${g.slug}`)];
const key = (slug:string[]) => slug.join("/");

function metaFor(path:string): Metadata {
  const service=services.find(x=>`services/${x.slug}`===path), project=projects.find(x=>`work/${x.slug}`===path), guide=guides.find(x=>`guides/${x.slug}`===path);
  const serviceTitles:Record<string,string>={"custom-software-development":"Custom Software Development Services | Abdullah Built","saas-development":"SaaS Development Services | Abdullah Built","web-application-development":"Web Application Development Services | Abdullah Built","api-integration-development":"API Integration Services | Abdullah Built","business-automation":"Business Process Automation Services | Abdullah Built","mvp-product-development":"MVP Development Services for Startups | Abdullah Built","ai-application-development":"AI Application Development Services | Abdullah Built","product-rescue":"Product Rescue & Software Stabilization | Abdullah Built"};
  const guideTitles:Record<string,string>={"hire-saas-developer":"Hire a SaaS Developer: Practical Guide | Abdullah Built","hire-web-app-developer":"Hire a Web App Developer: Practical Guide | Abdullah Built","startup-mvp-development":"Startup MVP Development Guide | Abdullah Built","custom-software-vs-saas":"Custom Software vs SaaS: Build or Buy | Abdullah Built","saas-mvp-development-cost":"SaaS MVP Development Cost & Scope | Abdullah Built","api-integration-planning":"API Integration Planning Guide | Abdullah Built","rescue-ai-built-web-app":"Rescue an AI-Built Web App | Abdullah Built","ai-feature-vs-automation":"AI Feature vs Automation | Abdullah Built","reliable-webhook-integration":"Reliable Webhook Integration Guide | Abdullah Built"};
  const title = service ? serviceTitles[service.slug] : project ? `${project.name} Software Case Study | Abdullah Built` : guide ? guideTitles[guide.slug] : path==="services" ? "Software Development Services | Abdullah Built" : path==="work" ? "Software Development Case Studies | Abdullah Built" : path==="guides" ? "Software Product Development Guides | Abdullah Built" : path==="about" ? "About Muhammad Abdullah | Product Engineer" : "Start a Software Project | Abdullah Built";
  const description = service?.description || project?.description || guide?.description || (path==="services" ? "Custom software, SaaS, web application, API integration, automation, and MVP development services for clients worldwide." : path==="work" ? "Case studies covering product engineering, developer tools, market intelligence, verified funding, and cross-chain payments." : path==="guides" ? "Practical guides for hiring software developers, scoping SaaS products, and planning a startup MVP." : path==="about" ? "Independent product builder and full-stack engineer turning complex ideas and workflows into working software." : "Share your software product, current stage, constraints, and what needs to be built.");
  const url=`/${path}/`;
  return { title, description, alternates:{canonical:url,languages:{en:url,"x-default":url}}, openGraph:{title,description,url,type:guide?"article":"website",images:[{url:"/og.png",width:1200,height:630,alt:"Muhammad Abdullah portfolio"}]}, twitter:{card:"summary_large_image",title,description,images:["/og.png"]} };
}

export function generateStaticParams(){ return routeList.map(route=>({slug:route.split("/")})); }
export async function generateMetadata({params}:{params:Promise<{slug:string[]}>}){ return metaFor(key((await params).slug)); }

function Header(){return <><a className="seo-skip" href="#main">Skip to content</a><header className="seo-header"><Link href="/" className="seo-wordmark">abdullah<span>.</span></Link><nav aria-label="Primary"><Link href="/work/">Work</Link><Link href="/services/">Services</Link><Link href="/guides/">Guides</Link><Link href="/about/">About</Link><Link href="/contact/">Contact</Link></nav></header></>}
function Footer(){return <footer className="seo-footer"><span>© 2026 Muhammad Abdullah</span><div><a href="mailto:mabdullah.built@gmail.com">Email</a><a href="https://www.linkedin.com/in/muhammad-abdullah-builder/">LinkedIn</a><a href="https://github.com/velz-cmd">GitHub</a><Link href="/contact/">Start a project</Link></div></footer>}
function Crumbs({items}:{items:{name:string,href?:string}[]}){return <nav className="seo-crumbs" aria-label="Breadcrumb">{items.map((x,i)=><span key={x.name}>{x.href?<Link href={x.href}>{x.name}</Link>:x.name}{i<items.length-1&&" / "}</span>)}</nav>}
function Cta({service,source}:{service?:string;source?:string}){const selected=services.find(item=>item.slug===service);const href=selected?`/contact/?service=${selected.slug}`:source?`/contact/?source=${source}`:"/contact/";return <section className="seo-cta"><p>PROJECT INQUIRY</p><h2>{selected?`Discuss your ${selected.name.toLowerCase()} project.`:"Tell me what you are trying to build."}</h2><p>Share the goal, current state, constraints, and useful links. I’ll help identify the most useful path forward.</p><div><Link className="seo-button" href={href} data-event="service_cta_click" data-service={selected?.slug || source || "general"}>{selected?`Start a ${selected.name.toLowerCase()} inquiry`:"Discuss your project"} <span>→</span></Link><a className="seo-text-link" href="https://cal.com/muhammad-abdullah-built/idea-to-product" data-event="book_call_click">Book a 15-minute fit call ↗</a></div></section>}
function Schema({data}:{data:object}){return <script type="application/ld+json" dangerouslySetInnerHTML={{__html:JSON.stringify(data)}}/>}

