function GuidePage({guide}:{guide:Guide}){
  const url=`${origin}/guides/${guide.slug}/`, ids=guide.sections.map(([h])=>h.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,""));
  const published=guide.published || "2026-09-24";
  const schema={"@context":"https://schema.org","@graph":[{"@type":"WebPage","@id":`${url}#webpage`,url,name:guide.title,description:guide.description,isPartOf:{"@id":`${origin}/#website`},dateModified:updated},{"@type":"Article","@id":`${url}#article`,headline:guide.title,description:guide.description,url,datePublished:published,dateModified:updated,author:{"@id":`${origin}/#person`},publisher:{"@id":`${origin}/#business`},inLanguage:"en"},{"@type":"BreadcrumbList",itemListElement:[{"@type":"ListItem",position:1,name:"Home",item:`${origin}/`},{"@type":"ListItem",position:2,name:"Guides",item:`${origin}/guides/`},{"@type":"ListItem",position:3,name:guide.title,item:url}]}]};
  const relatedService=services.find(service=>service.slug===guide.service)!;
  const relatedProjects=guide.proof.map(slug=>projects.find(project=>project.slug===slug)!);
  const relatedGuides=guides.filter(item=>item.slug!==guide.slug && (item.service===guide.service || item.category===guide.category)).slice(0,3);
  const sources=guideSources[guide.slug] || [];
  const wordCount=[guide.intro,...guide.sections.map(([,text])=>text)].join(" ").split(/\s+/).length+360;
  const readingTime=Math.max(4,Math.ceil(wordCount/220));
  return <><Schema data={schema}/><Crumbs items={[{name:"Home",href:"/"},{name:"Guides",href:"/guides/"},{name:guide.title}]}/><article><header className="seo-hero seo-editorial-hero"><p>{guide.category.toUpperCase()} / BUYER GUIDE</p><h1>{guide.title}<span>.</span></h1><p>{guide.description}</p><small>By Muhammad Abdullah · Published {published==="2026-09-27"?"September 27, 2026":"September 24, 2026"} · Updated September 27, 2026 · {readingTime} min read</small></header><GuideVisual slug={guide.slug} headings={guide.sections.map(([heading])=>heading)}/><div className="seo-prose"><p className="seo-lede">{guide.intro}</p><nav className="seo-toc" aria-label="On this page"><strong>On this page</strong>{guide.sections.map(([heading],i)=><a key={heading} href={`#${ids[i]}`}>{heading}</a>)}</nav>{guide.sections.map(([heading,text],i)=><section key={heading} id={ids[i]}><h2>{heading}</h2><p>{text}</p></section>)}<h2>Decision checklist</h2><ul><li>Write the first user and the result they need.</li><li>List the records, roles, and external systems required for that result.</li><li>Define acceptance conditions for the critical path and its failure states.</li><li>Confirm repository, hosting, accounts, data, and documentation ownership.</li><li>Separate launch-critical work from assumptions that can wait for evidence.</li></ul><h2>Common mistakes</h2><ul><li>Choosing by framework keywords without reviewing product reasoning.</li><li>Estimating a screen count while ignoring data, permissions, and operations.</li><li>Treating deployment, monitoring, and handoff as work for later.</li><li>Adding broad scope before one complete workflow is usable.</li></ul><h2>Use a clear written boundary</h2><p>Document the first user, main task, required records, integrations, acceptance conditions, ownership, and what is deliberately out of scope. This makes estimates and reviews more concrete and keeps the engagement focused on a working outcome.</p>{sources.length>0&&<><h2>Primary references</h2><p>These official resources support the implementation details and should be checked again when provider behavior changes.</p><ul>{sources.map(source=><li key={source.href}><a href={source.href}>{source.label} ↗</a></li>)}</ul></>}<h2>See the approach in working products</h2><div className="seo-related">{relatedProjects.map(project=><Link key={project.slug} href={`/work/${project.slug}/`} data-event="case_study_click">{project.name} case study ↗</Link>)}<Link href={`/services/${relatedService.slug}/`} data-event="guide_to_service_click">{relatedService.name} ↗</Link></div>{relatedGuides.length>0&&<><h2>Continue this topic</h2><div className="seo-related">{relatedGuides.map(item=><Link key={item.slug} href={`/guides/${item.slug}/`}>{item.title} ↗</Link>)}</div></>}<aside className="seo-author"><img src="/assets/abdullah.png" width="96" height="96" loading="lazy" alt="Muhammad Abdullah"/><div><strong>Written by Muhammad Abdullah</strong><p>Independent product builder and full-stack engineer working across product design, web applications, integrations, automation, AI workflows, and deployment.</p><Link href="/about/">About the author ↗</Link></div></aside></div></article><Cta service={relatedService.slug}/></>;
}

